        vm.assume(_recipient != address(0));
        vm.recordLogs();
        c.setRewardsRecipient(_recipient);
        Vm.Log[] memory entries = vm.getRecordedLogs();
        address emittedRecipient;
        for (uint i = 0; i < entries.length; i++) {
            if (entries[i].topics[0] == keccak256("SetRewardsRecipient(address)")) {
                emittedRecipient = abi.decode(entries[i].data, (address));
                break;
            }
        }
        assertEq(emittedRecipient, c.rewardsRecipient());
    }
}

