pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }
    function testFuzz_property(address recipient, uint8 rewardTokensLen) public {
        // 1. Bound rewardTokensLen to keep it in a wide admissible domain (at least 1 to allow token transfers)
        rewardTokensLen = uint8(bound(rewardTokensLen, 1, 10));
        // Build a dynamic reward tokens array with random addresses
        address[] memory tokens = new address[](rewardTokensLen);
        for (uint i = 0; i < rewardTokensLen; i++) {
            tokens[i] = address(uint160(uint256(keccak256(abi.encode(recipient, i)))));
        }
        // Deploy a new contract with these reward tokens and the initial recipient set to address(0)
        c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), tokens);

        // 2. Drive c through setRewardsRecipient with the fuzzed recipient
        vm.prank(address(this));
        c.setRewardsRecipient(recipient);

        // 3. Check: Since rewardsRecipient is never updated in the buggy version,
        // the stored value remains address(0) instead of the argument.
        // The correct version stores the argument.
        // Because rewardsRecipient is a public state variable, it has an auto-generated getter.
        assertEq(c.rewardsRecipient(), recipient, "rewardsRecipient must equal set argument");
    }
}

