pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint32 pid, address token, address rewards, bool shutdown) public {
        vm.assume(token != address(0) && rewards != address(0));
        vm.assume(pid > 0);
        // The booster is a precompile/mock? We can't directly set poolInfo. Instead, we observe that if the booster's view function reports some shutdown status,
        // isCvxShutdown must match it. But we need to drive the test through c's interface only.
        // Since we cannot mock or set booster state via vm.mockCall (rejected), we instead rely on the fact that c.setCvxPoolInfo sets cvxPoolInfo.pId,
        // and isCvxShutdown reads booster.poolInfo(cvxPoolInfo.pId).shutdown.
        // We set the cvxPoolInfo and then compare isCvxShutdown with the booster's response.
        c.setCvxPoolInfo(pid, token, rewards);
        bool actualShutdown = c.booster().poolInfo(pid).shutdown;
        bool result = c.isCvxShutdown();
        assertEq(result, actualShutdown, "isCvxShutdown must match booster poolInfo shutdown");
    }
}

